import { Backdrop, CircularProgress, Container, Stack } from "@mui/material";
import { State } from "../../models/core/my-react";
import { ApiState, ApiStoredState } from "../../configs/apis";
import AppScaffold from "../../layouts/AppScaffold";
import { useWidth } from "../../configs/breakpoints";
import ProductsProducts from "./layouts/ProductsProducts";
import { useNavigate, useParams } from "react-router-dom";
import ProductsCategories from "./layouts/ProductsCategories";
import ProductsBrands from "./layouts/ProductsBrands";
import { useTranslation } from "../../configs/translation";

const ProductsPage = ({ type = null }) => {
  const navigate = useNavigate();
  const { forLocale } = useTranslation();
  const { page, categoryId, brandId, search, order } = useParams();
  const { forDevice, forSize } = useWidth();

  const fthresh = forSize(2, 3, 4, 5, 6) * 4;

  const fpage = State(page ?? 1);
  const fcategoryId = State(categoryId ?? null);
  const fbrandId = State(brandId ?? null);
  const fsearch = State((search && decodeURIComponent(search)) ?? null);
  const forder = State((order && decodeURIComponent(order)) ?? null);

  const homeData = ApiStoredState("public/ecommerce/home");
  const productsData = ApiState("public/ecommerce/products/get", {
    bodyData: {
      thresh: fthresh,
      page: fpage.value,
      ...(fcategoryId.value ? { category_id: fcategoryId.value } : {}),
      ...(fbrandId.value ? { brand_id: fbrandId.value } : {}),
      ...(fsearch.value ? { search: fsearch.value } : {}),
      ...(forder.value ? { order: forder.value } : {}),
    },
  });

  // products products
  const loadProducts = ({
    p = fpage.value,
    c = fcategoryId.value,
    b = fbrandId.value,
    s = fsearch.value,
    o = forder.value,
  } = {}) => {
    productsData.callApi({
      thresh: fthresh,
      page: p,
      ...(c ? { category_id: c } : {}),
      ...(b ? { brand_id: b } : {}),
      ...(s ? { search: s } : {}),
      ...(o ? { order: o } : {}),
    });
    productsNavigate({ p, c, b, s, o });
  };
  const productsNavigate = ({
    p = fpage.value,
    c = fcategoryId.value,
    b = fbrandId.value,
    s = fsearch.value,
    o = forder.value,
  } = {}) => {
    let url = `/products`;

    if (type === "categories") url += `/categories/${categoryId}`;
    if (type === "brands") url += `/brands/${brandId}`;

    if (p) url += `/p/${p}`;
    if (type !== "categories" && c) url += `/c/${c}`;
    if (type !== "brands" && b) url += `/b/${b}`;
    if (s) url += `/s/${encodeURIComponent(s)}`;
    if (o) url += `/o/${encodeURIComponent(o)}`;
    navigate(url);
  };

  return (
    <AppScaffold
      search={fsearch.value}
      onSearchChange={(s) => {
        fsearch.value = s;
        loadProducts({ s: s });
      }}
    >
      <Container maxWidth={"desktop"} sx={{ my: forDevice(2, null, 4) }}>
        <Stack spacing={forDevice(1, null, 2)}>
          {type !== "categories" && (
            <ProductsCategories
              categoryId={fcategoryId}
              onChange={(val) => {
                fcategoryId.value = val;
                loadProducts({ c: val });
              }}
              categories={homeData.value?.categories}
              brandId={fbrandId}
              brands={homeData.value?.brands}
            />
          )}
          {type !== "brands" && (
            <ProductsBrands
              brandId={fbrandId}
              onChange={(val) => {
                fbrandId.value = val;
                loadProducts({ b: val });
              }}
              brands={homeData.value?.brands}
              categoryId={fcategoryId}
              categories={homeData.value?.categories}
            />
          )}
          <ProductsProducts
            key={productsData.namespace}
            products={productsData.value?.products}
            page={fpage.value}
            pages={productsData.value?.pages}
            results={productsData.value?.results}
            onPageChange={(val) => {
              fpage.value = val;
              loadProducts({ p: val });
            }}
            order={forder.value}
            onOrderChange={(val) => {
              forder.value = val;
              loadProducts({ o: val });
            }}
            category={
              homeData.value?.categories.find(
                (o) => o.id === fcategoryId.value
              )?.[forLocale({ ar: "name_alt" }, "name")]
            }
            clearCategory={() => {
              fcategoryId.value = null;
              loadProducts({ c: null });
            }}
            brand={
              homeData.value?.brands.find((o) => o.id === fbrandId.value)?.[
                forLocale({ ar: "name_alt" }, "name")
              ]
            }
            clearBrand={() => {
              fbrandId.value = null;
              loadProducts({ b: null });
            }}
            search={fsearch.value}
            clearSearch={() => {
              fsearch.value = null;
              loadProducts({ s: null });
            }}
          />
        </Stack>
        <Backdrop
          sx={{ color: "primary", zIndex: (theme) => theme.zIndex.drawer + 1 }}
          open={productsData.waiting}
        >
          <CircularProgress color="inherit" />
        </Backdrop>
      </Container>
    </AppScaffold>
  );
};
export default ProductsPage;
