import { Container, Stack } from "@mui/material";
import { ApiStoredState } from "../../configs/apis";
import AppScaffold from "../../layouts/AppScaffold";
import HomeCategories from "./layouts/HomeCategories";
import { useWidth } from "../../configs/breakpoints";
import HomeBrands from "./layouts/HomeBrands";
import HomeProducts from "./layouts/HomeProducts";
import { useTranslation } from "../../configs/translation";

const HomePage = () => {
  const { t } = useTranslation();
  const { forDevice, forSize } = useWidth();
  const fthresh = forSize(2, 3, 4, 5, 6) * 2;

  const homeData = ApiStoredState("public/ecommerce/home");
  const productsData = ApiStoredState("public/ecommerce/products/get", {
    namespace: "home_trending_products",
    bodyData: {
      thresh: fthresh,
    },
  });

  return (
    <AppScaffold>
      <Container maxWidth={"desktop"} sx={{ my: forDevice(2, null, 4) }}>
        <Stack spacing={forDevice(2, null, 4)}>
          <HomeCategories categories={homeData.value?.categories} />
          <HomeBrands brands={homeData.value?.brands} />
          <HomeProducts
            title={t("trending_products")}
            products={productsData.value?.products}
          />
        </Stack>
      </Container>
    </AppScaffold>
  );
};
export default HomePage;
