import { useEffect, useState } from "react";
import { eApiCaller, eDate, eError, eList, eSuccess } from "../models/core/my-js";

//==============================< eapi state
export const ApisEB = new eApiCaller(
    "https://dev.exabytellc.com/_/Exa/BE/ERP/API/", {
    defaultHeaders: {
        "User-Timezone": eDate.now.timezoneOffset,
    },
    defaultBodyData: {
        //"SID": "UXZFWHcyM0daVCtRZEE9PTpvMzFzZUJybHZHUjUvNVFhMmdqczNBPT0=", // OTH SID
        "SID": "d2prRkZJY3QvVXlkOkFCRmFyZXVyRWlTM2ZUNnh3K0k4YkE9PQ==", // GH SID
    },
    bodyDataType: "formdata",
    responseType: "json",
    responseHandler: (request) => {
        // request error
        if (request.httpCode !== 200) {
            return eError("server_error");
        }
        // api error
        let response = request.response;
        if (response.status !== 200) {
            // any error
            return eError(`${response.status}:${response.statusText}:${response.error}`, response.data);
        }
        // success
        return eSuccess(response.message, response.data);
    }
});
ApisEB.getMedia = function (url) {
    if (url) return this.baseUrl + "_media/" + url;
    return null;
}

//==============================< eapi state
export const ApiStoredState = (url, { bodyData, namespace = "", autoNS = true, autoCall = true } = {}) => {
    const getNamespace = (namespace, bodyData) => {
        if (!autoNS) {
            return namespace;
        } else {
            return `${namespace}:${eList.objToUrlData(bodyData ?? {})}`;
        }
    }

    const [getN, setN] = useState(getNamespace(namespace, bodyData))
    const [getW, setW] = useState(false);
    const [getV, setV] = useState(ApisEB.checkStored(url, getN)?.data ?? null);

    const callApi = (bd, ns = namespace) => {
        setW(true);
        setV(null);
        setTimeout(async () => {
            setN(getNamespace(ns, bd))
            let r = await ApisEB.callStored(url, {
                method: "POST",
                bodyData: bd,
                namespace: getN,
            });
            setW(false);
            if (r.success === false) {
                console.log(r.message, r.data);
                alert(r.message);
            } else {
                setV(r.data);
            }
        }, 10);
    }

    // auto call api
    useEffect(() => {
        if (autoCall === true && !getV) {
            callApi(bodyData, namespace);
        }
        // eslint-disable-next-line
    }, []);

    return {
        get value() {
            return getV;
        },
        get waiting() {
            return getW;
        },
        get namespace() {
            return getN;
        },
        callApi: callApi,
    };
};
//==============================< eapi state
export const ApiState = (url, { bodyData, autoCall = true } = {}) => {
    const [getW, setW] = useState(false);
    const [getV, setV] = useState(null);

    const callApi = (bd) => {
        setW(true);
        setV(null);
        setTimeout(async () => {
            let r = await ApisEB.call(url, {
                method: "POST",
                bodyData: bd,
            });
            setW(false);
            if (r.success === false) {
                console.log(r.message, r.data);
                alert(r.message);
            } else {
                setV(r.data);
            }
        }, 10);
    }

    // auto call api
    useEffect(() => {
        if (autoCall === true && !getV) {
            callApi(bodyData);
        }
        // eslint-disable-next-line
    }, []);

    return {
        get value() {
            return getV;
        },
        get waiting() {
            return getW;
        },
        callApi: callApi,
    };
};