import {
  Box,
  Divider,
  Skeleton,
  Stack,
  Typography,
  useTheme,
} from "@mui/material";
import { useWidth } from "../../../configs/breakpoints";
import { useTranslation } from "../../../configs/translation";
import { eList, eNum } from "../../../models/core/my-js";
import AppHtmlViewer from "../../../layouts/AppHtmlViewer";
import AppProductCartBtn from "../../../layouts/AppProductCartBtn";
import AppProductFavBtn from "../../../layouts/AppProductFavBtn";
import MyTabSlider, {
  MyTabSliderImage,
  MyTabSliderLabel,
} from "../../../components/MyTabSlider";
import { ApisEB } from "../../../configs/apis";

const ProductTitle = ({ productId, product, variants }) => {
  const { t, forLocale } = useTranslation();
  const isPriced = product?.price && product?.price > 0;
  const isOutStock = !product?.stock || product?.stock === "0";
  const theme = useTheme();
  const { forDevice } = useWidth();

  const manageVariants = () => {
    var options = variants?.options;
    var products = variants?.variants;
    //empty
    if (
      !options ||
      !products ||
      options?.length === 0 ||
      products?.length === 0
    )
      return null;
    // not empty
    var currprod = products.find((o) => o.id === productId);
    if (!currprod) return null;
    // loop through options
    var results = [];
    for (var option of options) {
      var selected = currprod.options.find(
        (o) => o.basis_id === option.id
      )?.value_id;
      var values = [];
      var selectedIndex = -1;
      for (var value of option.values) {
        // selected
        if (value.id === selected) {
          values.push({ value, product: currprod });
          selectedIndex = values.length - 1;
        } // not selected
        else {
          for (var prod of products) {
            var currOption = false;
            var sameOptions = true;
            //
            for (var poption of prod.options) {
              if (
                poption.basis_id === option.id &&
                poption.value_id === value.id
              ) {
                currOption = true;
              }
              if (
                poption.basis_id !== option.id &&
                !currprod.options.find(
                  (o) =>
                    o.basis_id === poption.basis_id &&
                    o.value_id === poption.value_id
                )
              ) {
                sameOptions = false;
              }
            }
            //
            if (currOption === true && sameOptions === true) {
              values.push({ value, product: prod });
            }
          }
        }
      }
      if (values.length > 0) {
        results.push({ option, values, selectedIndex });
      }
    }
    if (results.length > 0) {
      return results;
    }
    return null;
  };
  var variantsAcc = manageVariants();

  if (!product) {
    return (
      <Stack spacing={3} px={1} mt={1}>
        <Skeleton variant="rectangular" width="90%" height={25} />
        <Skeleton variant="rectangular" width="40%" height={15} />

        <Divider />

        <Skeleton variant="rectangular" width="50%" height={15} />
        <Skeleton variant="rectangular" width="50%" height={15} />
        <Skeleton variant="rectangular" width="50%" height={15} />
        <Skeleton variant="rectangular" width="75%" height={50} />

        <Divider />

        <Skeleton variant="rectangular" width="75%" height={100} />

        <Divider />

        <Skeleton variant="rectangular" width="75%" height={30} />
      </Stack>
    );
  } else {
    return (
      <Stack spacing={2} mt={1}>
        <Stack spacing={3} px={1}>
          <Typography variant="h5" sx={{ fontWeight: "bold" }}>
            {product?.[forLocale({ ar: "name_alt" }, "name")]}
          </Typography>

          {isPriced && (
            <Box>
              <Typography
                variant="h4"
                component="span"
                color={isOutStock ? "primary" : "secondary"}
                sx={{ fontWeight: "bold" }}
              >
                {eNum.readable(parseFloat(product?.price), 0)}
              </Typography>
              <Typography
                variant="subtitle1"
                component="span"
                color={isOutStock ? "primary" : "secondary"}
                sx={{ px: 0.25 }}
              >
                {t("currency")}
              </Typography>
            </Box>
          )}
        </Stack>

        {!product?.sku &&
        !product?.model &&
        !product?.part_no &&
        !product?.brief ? null : (
          <Divider />
        )}

        <Stack spacing={2} px={1}>
          {product?.sku && (
            <Box>
              <Typography variant="subtitle1" component="span">
                {t("sku") + ":"}
              </Typography>
              <Typography
                variant="h6"
                component="span"
                sx={{ fontWeight: "bold", px: 1 }}
              >
                {product?.sku}
              </Typography>
            </Box>
          )}

          {product?.model && (
            <Box>
              <Typography variant="subtitle1" component="span">
                {t("model") + ":"}
              </Typography>
              <Typography
                variant="h6"
                component="span"
                sx={{ fontWeight: "bold", px: 1 }}
              >
                {product?.model}
              </Typography>
            </Box>
          )}

          {product?.part_no && (
            <Box>
              <Typography variant="subtitle1" component="span">
                {t("part_no") + ":"}
              </Typography>
              <Typography
                variant="h6"
                component="span"
                sx={{ fontWeight: "bold", px: 1 }}
              >
                {product?.part_no}
              </Typography>
            </Box>
          )}

          {product?.brief && (
            <Box>
              <AppHtmlViewer
                html={product?.[forLocale({ ar: "brief_alt" }, "brief")]}
                alignItems="start"
              />
            </Box>
          )}
        </Stack>

        {variantsAcc && (
          <>
            <Divider />
            <Stack
              direction={"column"}
              alignItems={"start"}
              spacing={2}
              px={1}
              children={eList.fromArray(variantsAcc, (index, item) => (
                <Box key={`pvo-${index}-${productId}`} sx={{ width: "100%" }}>
                  <Typography
                    variant={"subtitle1"}
                    sx={{
                      color: "primary2",
                    }}
                    children={
                      item.option?.[forLocale({ ar: "name_alt" }, "name")]
                    }
                  />
                  <MyTabSlider
                    value={item.selectedIndex}
                    key={`pvvs-${index}-${productId}`}
                    data={item.values}
                    scrollButtons={forDevice(false, null, "auto")}
                    customKey={(item) => item.product.id}
                    iconPosition="start"
                    linkTo={(index, item) => `/product/${item.product.id}`}
                    sx={(selected) => {
                      return {
                        borderWidth: 2,
                        borderStyle: "solid",
                        borderColor: selected
                          ? theme.palette.secondary.main
                          : theme.palette.light.main,
                        bgcolor: theme.palette.light.main,
                      };
                    }}
                    label={(item, selected) =>
                      MyTabSliderLabel({
                        variant: "subtitle1",
                        text: item.value?.[
                          forLocale({ ar: "name_alt" }, "name")
                        ],
                        maxLines: null,
                        px: 1,
                        py: 0.5,
                        color: selected
                          ? theme.palette.secondary.main
                          : theme.palette.primary.main,
                      })
                    }
                    icon={
                      item.option.thumbnail === "1"
                        ? (item, selected) =>
                            MyTabSliderImage({
                              src: ApisEB.getMedia(item.product.thumbnail),
                              alt: item.product?.[
                                forLocale({ ar: "name_alt" }, "name")
                              ],
                              width: 40,
                              height: 40,
                            })
                        : null
                    }
                  />
                </Box>
              ))}
            />
          </>
        )}

        {isPriced && (
          <>
            <Divider />
            <Stack
              direction={forDevice("column", null, "row")}
              alignItems={forDevice("center", "start")}
              spacing={2}
              px={1}
            >
              <AppProductCartBtn
                productId={productId}
                product={product}
                full={true}
                size={"large"}
                smP={false}
              />
              <AppProductFavBtn
                productId={productId}
                full={true}
                size={"large"}
              />
            </Stack>
          </>
        )}
      </Stack>
    );
  }
};

export default ProductTitle;
