//
import React from "react";
import AppBar from "@mui/material/AppBar";
import Toolbar from "@mui/material/Toolbar";
import Typography from "@mui/material/Typography";
import IconButton from "@mui/material/IconButton";
import Button from "@mui/material/Button";
import Container from "@mui/material/Container";
import Box from "@mui/material/Box";
import Badge from "@mui/material/Badge";
import Autocomplete from "@mui/material/Autocomplete";
import ButtonGroup from "@mui/material/ButtonGroup";
import Stack from "@mui/material/Stack";
import TextField from "@mui/material/TextField";
import { default as MuiLink } from "@mui/material/Link";
import { useTheme } from "@mui/material";
import {
  ArrowBackTwoTone,
  ArrowForwardTwoTone,
  BeenhereTwoTone,
  CategoryTwoTone,
  FavoriteTwoTone,
  HomeTwoTone,
  LanguageTwoTone,
  SearchTwoTone,
  ShoppingCartTwoTone,
  StorefrontTwoTone,
} from "@mui/icons-material";
import { Link, useNavigate } from "react-router-dom";
import { useTranslation } from "../configs/translation";
import { useBreakpoints, useWidth } from "../configs/breakpoints";
import MyImage from "../components/MyImage";
import LogoIcon from "../assets/images/logoIcon.png";
import Logo from "../assets/images/logo.png";
import { eList } from "../models/core/my-js";
import { useMyCart } from "../models/MyCart";
import { useMyFav } from "../models/MyFav";
import { State } from "../models/core/my-react";
import { ApiState } from "../configs/apis";

const AppHeader = ({ title, main, search, onSearchChange }) => {
  const { down } = useBreakpoints();
  const mobile = down("tablet");
  const options = ApiState("public/ecommerce/tags");

  return (
    <>
      <MobileMainHeader
        mobile={mobile}
        options={options.value?.tags}
        {...{ main, search, onSearchChange }}
      />
      <MobileSubHeader mobile={mobile} {...{ main, title }} />
      <DesktopHeader
        mobile={mobile}
        options={options.value?.tags}
        {...{ search, onSearchChange }}
      />
    </>
  );
};
export default AppHeader;

const MobileMainHeader = ({
  mobile,
  main,
  search,
  options,
  onSearchChange,
}) => {
  const theme = useTheme();
  const { t, setLocale, locales, locale } = useTranslation();
  const { forDevice } = useWidth();
  const navigate = useNavigate();
  const searching = State(false);
  const searchQ = State(search ?? null);

  return (
    mobile &&
    main && (
      <AppBar position="static" variant="dense" color="white">
        {!searching.value && (
          <Toolbar
            variant="dense"
            sx={{
              borderBottomWidth: 1,
              borderBottomStyle: "solid",
              borderBottomColor: theme.palette.light.main,
              px: 0.5,
            }}
            disableGutters
          >
            <MyImage
              src={LogoIcon}
              alt={t("welcome_greeting")}
              width={40}
              height={40}
            />
            <Typography
              variant="h6"
              textAlign={"start"}
              sx={{ flexGrow: 1, px: 1 }}
              noWrap
            >
              {t("welcome_greeting")}
            </Typography>
            <Button
              onClick={() => {
                searching.value = true;
              }}
              size="small"
              variant="contained"
              color="light"
              sx={{ p: 0.5 }}
              disableElevation
            >
              <SearchTwoTone fontSize="medium" />
            </Button>
            <IconButton
              onClick={() => {
                var lk = Object.keys(locales);
                var l = lk.indexOf(locale);
                lk.splice(l, 1);

                setLocale(lk[0]);
              }}
              size="small"
              variant="outlined"
              color="secondary"
            >
              <LanguageTwoTone />
            </IconButton>
          </Toolbar>
        )}
        {searching.value && (
          <Toolbar
            variant="dense"
            sx={{
              borderBottomWidth: 1,
              borderBottomStyle: "solid",
              borderBottomColor: theme.palette.light.main,
              px: 0.5,
              py: 0.5,
              height: forDevice(40, 50),
            }}
            disableGutters
          >
            <SearchBar
              t={t}
              navigate={navigate}
              fullWidth={true}
              searching={searching}
              searchQ={searchQ}
              options={options}
              onSearchChange={onSearchChange}
              small={true}
            />
          </Toolbar>
        )}
      </AppBar>
    )
  );
};
const MobileSubHeader = ({ mobile, main, title }) => {
  const theme = useTheme();
  const { forDir, setLocale, locales, locale } = useTranslation();
  const navigate = useNavigate();

  return (
    mobile &&
    !main && (
      <AppBar position="static" variant="dense" color="white">
        <Toolbar
          variant="dense"
          sx={{
            borderBottomWidth: 1,
            borderBottomStyle: "solid",
            borderBottomColor: theme.palette.light.main,
            px: 0.5,
          }}
          disableGutters
        >
          <Button
            onClick={() => {
              navigate(window.history.length > 1 ? -1 : "/");
            }}
            size="small"
            variant="contained"
            color="light"
            sx={{ p: 0.5 }}
            disableElevation
          >
            {forDir(
              <ArrowBackTwoTone fontSize="small" />,
              <ArrowForwardTwoTone fontSize="small" />
            )}
          </Button>
          <Typography
            variant="subtitle1"
            textAlign={"center"}
            sx={{ flexGrow: 1, px: 1 }}
            noWrap
          >
            {title}
          </Typography>
          <IconButton
            onClick={() => {
              var lk = Object.keys(locales);
              var l = lk.indexOf(locale);
              lk.splice(l, 1);

              setLocale(lk[0]);
            }}
            size="small"
            color="secondary"
          >
            <LanguageTwoTone />
          </IconButton>
        </Toolbar>
      </AppBar>
    )
  );
};
const DesktopHeader = ({ mobile, search, options, onSearchChange }) => {
  const { t, setLocale, locales, locale } = useTranslation();
  const { forDevice } = useWidth();
  const navigate = useNavigate();
  const { favCount } = useMyFav();
  const { cartCount } = useMyCart();
  const searchQ = State(search ?? null);

  return (
    !mobile && (
      <>
        <AppBar position="static" variant="dense" color="white">
          <Container maxWidth={"desktop"}>
            <Toolbar
              variant="dense"
              sx={{
                py: 1.75,
                gap: forDevice(null, 2, 3, 4),
                height: forDevice(null, 65, 75),
              }}
              disableGutters
            >
              <MyImage
                src={Logo}
                alt={t("welcome_greeting")}
                width={"auto"}
                height={"100%"}
                style={{ borderRadius: 4 }}
              />
              <Box height={"100%"} sx={{ flexGrow: 1 }}>
                <SearchBar
                  t={t}
                  navigate={navigate}
                  fullWidth={true}
                  height={"100%"}
                  searchQ={searchQ}
                  options={options}
                  onSearchChange={onSearchChange}
                />
              </Box>
              <Stack direction={"column"}>
                <MuiLink href="tel:201023966756" underline="hover">
                  <Typography className="ltr enFonts" noWrap>
                    {"+2 0102 396 6756"}
                  </Typography>
                </MuiLink>
                <MuiLink href="tel:201221722221" underline="hover">
                  <Typography className="ltr enFonts" noWrap>
                    {"+2 0122 172 2221"}
                  </Typography>
                </MuiLink>
              </Stack>
            </Toolbar>
          </Container>
        </AppBar>
        <AppBar
          position="static"
          variant="dense"
          color="primary"
          sx={{ mb: 1 }}
        >
          <Container maxWidth={"desktop"}>
            <Toolbar
              variant="dense"
              sx={{
                py: 1,
                gap: forDevice(null, 1, 2, 3),
              }}
              disableGutters
            >
              {eList.fromArray(
                [
                  {
                    n: t("home"),
                    i: <HomeTwoTone />,
                    u: "/",
                  },
                  {
                    n: t("store"),
                    i: <StorefrontTwoTone />,
                    u: "/products",
                  },
                  {
                    n: t("categories"),
                    i: <CategoryTwoTone />,
                    u: "/categories",
                  },
                  {
                    n: t("brands"),
                    i: <BeenhereTwoTone />,
                    u: "/brands",
                  },
                ],
                (index, item) => (
                  <Link
                    key={`hl-${index}`}
                    to={item.u}
                    style={{
                      display: "contents",
                      textDecoration: "none",
                      color: "inherit",
                    }}
                  >
                    <Button
                      size="large"
                      variant="text"
                      color="inherit"
                      disableElevation
                      startIcon={item.i}
                    >
                      {item.n}
                    </Button>
                  </Link>
                )
              )}
              <Box sx={{ flexGrow: 1 }} />
              <Link
                to={"/favorites"}
                style={{
                  display: "contents",
                  textDecoration: "none",
                  color: "inherit",
                }}
              >
                <IconButton onClick={() => {}} color="inherit" size={"medium"}>
                  <Badge badgeContent={favCount()} color="secondary">
                    <FavoriteTwoTone />
                  </Badge>
                </IconButton>
              </Link>

              <Link
                to={"/cart"}
                style={{
                  display: "contents",
                  textDecoration: "none",
                  color: "inherit",
                }}
              >
                <IconButton onClick={() => {}} color="inherit" size={"medium"}>
                  <Badge badgeContent={cartCount()} color="secondary">
                    <ShoppingCartTwoTone />
                  </Badge>
                </IconButton>
              </Link>

              <IconButton
                onClick={() => {
                  var lk = Object.keys(locales);
                  var l = lk.indexOf(locale);
                  lk.splice(l, 1);

                  setLocale(lk[0]);
                }}
                color="inherit"
                size="medium"
              >
                <LanguageTwoTone />
              </IconButton>
            </Toolbar>
          </Container>
        </AppBar>
      </>
    )
  );
};

const SearchBar = ({
  t,
  navigate,
  fullWidth,
  height = "auto",
  searching,
  searchQ,
  options,
  onSearchChange,
  small = false,
}) => {
  return (
    <ButtonGroup fullWidth={fullWidth} sx={{ height: height }}>
      <Autocomplete
        freeSolo={true}
        disableClearable={false}
        value={searchQ.value}
        options={options ?? [""]}
        fullWidth={fullWidth}
        sx={{
          height: height,
          borderEndEndRadius: 0,
          borderStartEndRadius: 0,
        }}
        onInputChange={(e, v) => (searchQ.value = v)}
        onBlur={() => {
          if (searching?.value) searching.value = false;
        }}
        onChange={(e, v) => {
          searchQ.value = v;
          if (onSearchChange) onSearchChange(v);
          else {
            if (v) {
              navigate(`/products/p/1/s/${encodeURIComponent(v)}`);
            }
          }
        }}
        filterOptions={(options, state) => {
          let sq = state.inputValue.toLowerCase();
          sq = [sq, ...sq.split(" ")];
          return options
            ?.sort((a, b) => {
              return query(a, sq) - query(b, sq);

              function query(value, querys) {
                let p = 0;
                for (let q of querys) {
                  if (value.toLowerCase().indexOf(q) > -1) p++;
                }
                return -p;
              }
            })
            ?.slice(0, 10);
        }}
        renderInput={(params) => {
          if (params?.InputProps) {
            params.InputProps.sx = {
              ...(params?.InputProps?.sx ?? {}),
              height: height,
              borderEndEndRadius: 0,
              borderStartEndRadius: 0,
            };
          }
          return (
            <TextField
              {...params}
              placeholder={t("search_hint")}
              size="small"
              sx={{
                height: height,
                borderEndEndRadius: 0,
                borderStartEndRadius: 0,
              }}
              autoFocus={!!searching?.value}
            />
          );
        }}
      />
      <Button
        onClick={() => {
          console.log("cc", searchQ.value);
          if (onSearchChange) onSearchChange(searchQ.value);
          else {
            if (searchQ.value) {
              navigate(`/products/p/1/s/${encodeURIComponent(searchQ.value)}`);
            }
          }
          if (searching?.value) searching.value = false;
        }}
        variant="contained"
        size={small ? "medium" : "large"}
        color="primary"
        disableElevation
        fullWidth={false}
        sx={{ height: height, px: small ? 0.5 : 2, py: small ? 0.5 : 1 }}
      >
        <SearchTwoTone />
      </Button>
    </ButtonGroup>
  );
};
