import {
  Box,
  Chip,
  FormControl,
  MenuItem,
  Pagination,
  Select,
  Skeleton,
  Stack,
  Typography,
} from "@mui/material";
import AppProductCardGrid from "../../../layouts/AppProductCardGrid";
import { useWidth } from "../../../configs/breakpoints";
import { eList, eNum } from "../../../models/core/my-js";
import { useTranslation } from "../../../configs/translation";
import {
  BeenhereTwoTone,
  CategoryTwoTone,
  SearchTwoTone,
} from "@mui/icons-material";

const ProductsProducts = ({
  products,
  page,
  pages,
  results,
  onPageChange,
  order,
  onOrderChange,
  category,
  clearCategory,
  brand,
  clearBrand,
  search,
  clearSearch,
}) => {
  const { forSize, forDevice } = useWidth();
  const { t } = useTranslation();

  const chips = (category || brand || search) && (
    <Stack
      direction={"row"}
      justifyContent={"end"}
      alignItems={"center"}
      sx={{ width: "100%" }}
      spacing={forDevice(1, null, 2)}
      flexWrap={"wrap"}
      children={eList.fromArray(
        [
          {
            i: <CategoryTwoTone />,
            n: category,
            c: clearCategory,
          },
          {
            i: <BeenhereTwoTone />,
            n: brand,
            c: clearBrand,
          },
          {
            i: <SearchTwoTone />,
            n: search,
            c: clearSearch,
          },
        ],
        (index, val) => {
          if (val.n) {
            return (
              <Chip
                key={`fdc-${val.n}`}
                color="secondary"
                size={"small"}
                icon={val.i}
                label={val.n}
                variant="outlined"
                onClick={val.c}
                onDelete={val.c}
              />
            );
          }
        }
      )}
    ></Stack>
  );

  if (!products) {
    return (
      <Stack direction={"column"} spacing={1}>
        <Skeleton variant="rounded" height={25} />
        <Skeleton variant="rounded" height={1000} />
        <Skeleton variant="rounded" height={50} />
      </Stack>
    );
  } else if (products?.length > 0) {
    return (
      <Stack direction={"column"} spacing={1} alignItems={"center"}>
        <Stack
          direction={"row"}
          justifyContent={"space-between"}
          alignItems={"center"}
          sx={{ width: "100%" }}
          spacing={forDevice(1, null, 2)}
        >
          <Stack
            direction={"row"}
            justifyContent={"start"}
            alignItems={"center"}
            sx={{ width: "max-content" }}
            spacing={0.5}
          >
            <Typography variant="subtitle2">{t("results") + ":"}</Typography>
            <Typography variant="subtitle1" sx={{ fontWeight: "bold" }}>
              {eNum.readable(parseFloat(results ?? 0), 0)}
            </Typography>
          </Stack>

          <Box sx={{ flexGrow: 1 }}>{forDevice(null, null, chips)}</Box>

          <FormControl size="small" variant="standard" sx={{ minWidth: 120 }}>
            <Select
              value={order ?? ""}
              onChange={(event) => onOrderChange(event.target.value)}
              displayEmpty={true}
            >
              {eList.fromArray(
                [
                  { v: "", n: <em>{t("order")}</em> },
                  { v: "recent", n: t("recent") },
                  { v: "featured", n: t("featured") },
                  { v: "updated", n: t("updated") },
                  { v: "name-asc", n: t("name_asc") },
                  { v: "name-desc", n: t("name_desc") },
                  { v: "price-asc", n: t("price_asc") },
                  { v: "price-desc", n: t("price_desc") },
                ],
                (index, item) => (
                  <MenuItem key={`os-${index}`} value={item.v}>
                    {item.n}
                  </MenuItem>
                )
              )}
            </Select>
          </FormControl>
        </Stack>

        {forDevice(chips, null, "")}

        <AppProductCardGrid products={products} />
        <Pagination
          variant="outlined"
          shape="rounded"
          color="secondary"
          size={forDevice("small", null, "medium", "large")}
          siblingCount={forSize(2, 3, 4, 5, 6)}
          boundaryCount={forSize(0, 1, 2)}
          page={parseInt(page ?? 1)}
          count={parseInt(pages ?? 1)}
          onChange={(evt, val) => onPageChange(val)}
          showFirstButton={forSize(false, true)}
          showLastButton={forSize(false, true)}
        />
      </Stack>
    );
  } else {
    return null;
  }
};
export default ProductsProducts;
