import {
  Breadcrumbs,
  Divider,
  Skeleton,
  Stack,
  Typography,
  Link,
} from "@mui/material";
import { useTheme } from "@emotion/react";
import { useTranslation } from "../../../configs/translation";
import { ApisEB } from "../../../configs/apis";
import MyTabSlider, {
  MyTabSliderIcon,
  MyTabSliderImage,
  MyTabSliderLabel,
} from "../../../components/MyTabSlider";
import { useWidth } from "../../../configs/breakpoints";
import { eList } from "../../../models/core/my-js";
import { useRef } from "react";
import { BeenhereTwoTone } from "@mui/icons-material";

const ProductsBrands = ({
  brandId,
  onChange,
  brands,
  categoryId,
  categories,
}) => {
  const theme = useTheme();
  const { t, forLocale } = useTranslation();
  const { forDevice } = useWidth();
  const slidRef = useRef(null);

  const sw = forDevice(80, 85, 90);
  const sh = forDevice(30, 36, 42);

  // get lists
  const getData = () => {
    var fcat = categories?.find((obj) => obj?.id === categoryId?.value);
    var brands2 = brands;
    if (fcat) {
      brands2 = brands2?.filter((obj) => fcat?.brands.includes(obj?.id));
    }

    var bcarr = brands2?.find((obj) => obj?.id === brandId?.value);
    var v = 0;
    var i = brands2?.findIndex((obj) => obj?.id === brandId?.value);
    if (i > -1) v = i + 1;

    return {
      v: v,
      k: "brands",
      bc: [
        {
          id: null,
          name: t("brands"),
          name_alt: t("brands"),
        },
        ...(bcarr ? [bcarr] : []),
      ],
      ts: [
        {
          id: null,
          name: t("all"),
          name_alt: t("all"),
          icon: (
            <BeenhereTwoTone
              color="secondary"
              fontSize={forDevice("small", null, "medium")}
            />
          ),
        },
        ...(brands2 ?? []),
      ],
      arr: brands2,
    };
  };
  var lists = getData();

  if (!lists.arr) {
    return <Skeleton variant="rounded" height={90} />;
  } else if (lists.arr?.length > 0) {
    return (
      <Stack direction="column" spacing={forDevice(0, 1)} width={"100%"}>
        <Divider textAlign="left">
          <Breadcrumbs
            separator="›"
            sx={{ maxWidth: "100%", width: "max-content" }}
          >
            {eList.fromArray(lists.bc, (index, item) => {
              if (item?.id !== brandId.value) {
                return (
                  <Link
                    key={`${brandId.value}cbc-${index}`}
                    underline="hover"
                    color="secondary"
                    onClick={() => {
                      brandId.value = item?.id;
                      if (slidRef?.current) {
                        slidRef.current.setValue(0);
                      }
                      onChange(item?.id);
                    }}
                    sx={{ cursor: "pointer" }}
                    children={item?.[forLocale({ ar: "name_alt" }, "name")]}
                  />
                );
              } else {
                return (
                  <Typography
                    key={`${brandId.value}cbc-${index}`}
                    color="primary"
                    children={item?.[forLocale({ ar: "name_alt" }, "name")]}
                  />
                );
              }
            })}
          </Breadcrumbs>
        </Divider>
        <MyTabSlider
          ref={slidRef}
          value={lists.v}
          key={`mts-${lists.k}`}
          data={lists.ts}
          scrollButtons={forDevice(false, null, "auto")}
          customKey={(item) => item?.id}
          onChange={(index, item) => onChange(item?.id)}
          iconPosition="start"
          sx={(selected) => {
            return {
              borderColor: selected
                ? theme.palette.secondary.main
                : theme.palette.light.main,
              bgcolor: theme.palette.light.main,
            };
          }}
          label={(item, selected) =>
            MyTabSliderLabel({
              variant: "body2",
              text: item?.[forLocale({ ar: "name_alt" }, "name")],
              maxLines: null,
              px: 1,
              color: selected
                ? theme.palette.secondary.main
                : theme.palette.primary.main,
            })
          }
          icon={(item, selected) =>
            item.icon
              ? MyTabSliderIcon({
                  icon: item.icon,
                  width: sw,
                  height: sh,
                })
              : MyTabSliderImage({
                  src: ApisEB.getMedia(item?.thumbnail),
                  alt: item?.[forLocale({ ar: "name_alt" }, "name")],
                  width: sw,
                  height: sh,
                })
          }
        />
      </Stack>
    );
  } else {
    return null;
  }
};
export default ProductsBrands;
