import { Divider, Skeleton, Stack, Typography } from "@mui/material";
import { useTheme } from "@emotion/react";
import { useTranslation } from "../../../configs/translation";
import { ApisEB } from "../../../configs/apis";
import MyTabSlider, {
  MyTabSliderImage,
  MyTabSliderLabel,
} from "../../../components/MyTabSlider";
import { useWidth } from "../../../configs/breakpoints";
import { eList } from "../../../models/core/my-js";

const HomeCategories = ({ categories }) => {
  const theme = useTheme();
  const { t, forLocale } = useTranslation();
  const { forDevice } = useWidth();

  if (!categories) {
    return <Skeleton variant="rounded" height={125} />;
  } else if (categories?.length > 0) {
    var pCats = categories.filter((obj) => !obj?.parent_id);
    return (
      <Stack direction="column" spacing={2} width={"100%"}>
        <Divider textAlign="left">
          <Typography variant="h6">{t("categories")}</Typography>
        </Divider>
        <MyTabSlider
          data={pCats}
          scrollButtons={forDevice(false, null, "auto")}
          linkTo={(index, item) => {
            if (
              eList.arrCountIf(
                categories,
                (i, obj) => obj.parent_id === item.id
              ) > 0
            ) {
              return `/categories/${item.id}`;
            } else {
              return `/products/p/1/c/${item.id}`;
            }
          }}
          sx={(selected) => {
            return { borderColor: theme.palette.light.main };
          }}
          label={(item) =>
            MyTabSliderLabel({
              text: item?.[forLocale({ ar: "name_alt" }, "name")],
            })
          }
          icon={(item) =>
            MyTabSliderImage({
              src: ApisEB.getMedia(item?.thumbnail),
              alt: item?.[forLocale({ ar: "name_alt" }, "name")],
              width: 100,
              height: 100,
            })
          }
          width={100}
        />
      </Stack>
    );
  } else {
    return null;
  }
};
export default HomeCategories;
