import { useBreakpoints } from "../configs/breakpoints";
import { useTheme } from "@emotion/react";
import { useTranslation } from "../configs/translation";
import {
  AppBar,
  Badge,
  Box,
  Button,
  Container,
  Fab,
  Stack,
  Toolbar,
  Typography,
  Link,
  Grid,
  Divider,
} from "@mui/material";
import MyImage from "../components/MyImage";
import LogoIcon from "../assets/images/logoIcon.png";
import {
  EmailTwoTone,
  FavoriteTwoTone,
  GridViewTwoTone,
  MapTwoTone,
  PhoneTwoTone,
  ShoppingCartTwoTone,
  StorefrontTwoTone,
} from "@mui/icons-material";
import { BsWhatsapp } from "react-icons/bs";
import { eList } from "../models/core/my-js";
import { useMyFav } from "../models/MyFav";
import { useMyCart } from "../models/MyCart";
import Logo from "../assets/images/logo.png";

const AppFooter = ({ main }) => {
  const { down } = useBreakpoints();
  const mobile = down("tablet");

  return (
    <>
      <MainMobileFooter mobile={mobile} main={main} />
      <DektopFooter mobile={mobile} main={main} />
    </>
  );
};
export default AppFooter;

const MainMobileFooter = ({ mobile, main }) => {
  const theme = useTheme();
  const { t } = useTranslation();
  const { cartCount } = useMyCart();
  const { favCount } = useMyFav();

  return (
    mobile &&
    main && (
      <>
        <Box height={75} />
        <AppBar
          position="fixed"
          variant="dense"
          color="white"
          sx={{ top: "auto", width: "100%", bottom: 0 }}
        >
          <Toolbar
            variant="dense"
            sx={{
              width: "100%",
              borderTopWidth: 1,
              borderTopStyle: "solid",
              borderTopColor: theme.palette.light.main,
              px: 0.5,
              pt: 0.5,
            }}
            disableGutters
          >
            <Stack
              direction={"row"}
              spacing={0.5}
              sx={{
                width: "100%",
              }}
            >
              {eList.fromArray(
                [
                  {
                    n: <Typography variant="caption" children={t("store")} />,
                    i: <StorefrontTwoTone />,
                    u: "/products",
                  },
                  {
                    n: <Typography variant="caption" children={t("cart")} />,
                    i: (
                      <Badge
                        badgeContent={cartCount()}
                        color="secondary"
                        children={<ShoppingCartTwoTone />}
                      />
                    ),
                    u: "/cart",
                  },
                  {
                    sx: {
                      position: "relative",
                    },
                    c: (
                      <Fab
                        size="large"
                        color="primary"
                        sx={{
                          position: "absolute",
                          top: -20,
                          left: 0,
                          right: 0,
                          mx: "auto",
                          overflow: "hidden",
                        }}
                      >
                        <Link
                          to={"/"}
                          style={{
                            display: "contents",
                            textDecoration: "none",
                            color: "inherit",
                          }}
                        >
                          <MyImage
                            src={LogoIcon}
                            alt={t("welcome_greeting")}
                            width={"100%"}
                            height={"100%"}
                            bgColor={"transparent"}
                          />
                        </Link>
                      </Fab>
                    ),
                  },
                  {
                    n: (
                      <Typography variant="caption" children={t("favorites")} />
                    ),
                    i: (
                      <Badge
                        badgeContent={favCount()}
                        color="secondary"
                        children={<FavoriteTwoTone />}
                      />
                    ),
                    u: "/favorites",
                  },
                  {
                    n: <Typography variant="caption" children={t("more")} />,
                    i: <GridViewTwoTone />,
                    u: "/more",
                  },
                ],
                (index, item) => (
                  <Box
                    key={`mf-${index}`}
                    sx={{
                      ...(item.sx ?? {}),
                      flexGrow: 1,
                      flexShrink: 1,
                      flexBasis: 0,
                    }}
                  >
                    {!item.c && (
                      <Link
                        key={`hl-${index}`}
                        to={item.u}
                        style={{
                          display: "contents",
                          textDecoration: "none",
                          color: "inherit",
                        }}
                      >
                        <Button
                          size="large"
                          variant="text"
                          color="inherit"
                          disableElevation
                          fullWidth
                        >
                          <Stack
                            direction={"column"}
                            spacing={0.1}
                            alignItems={"center"}
                          >
                            {item.i}
                            {item.n}
                          </Stack>
                        </Button>
                      </Link>
                    )}
                    {item.c}
                  </Box>
                )
              )}
            </Stack>
          </Toolbar>
        </AppBar>
      </>
    )
  );
};
const DektopFooter = ({ mobile, main }) => {
  const { t } = useTranslation();

  return (
    !mobile && (
      <>
        <AppBar position="static" variant="dense" color="light" sx={{}}>
          <Container maxWidth={"desktop"}>
            <Toolbar
              variant="dense"
              sx={{
                width: "100%",
                py: 5,
              }}
            >
              <Grid container columnSpacing={1}>
                <Grid item xs={8}>
                  <Stack
                    direction={"column"}
                    justifyContent={"space-around"}
                    alignItems={"start"}
                    spacing={1}
                    sx={{
                      width: "100%",
                    }}
                  >
                    <MyImage
                      src={Logo}
                      alt={t("welcome_greeting")}
                      width={300}
                      imgWidth={"100%"}
                      height={"auto"}
                      style={{ borderRadius: 4 }}
                    />

                    <Typography
                      variant={"subtitle1"}
                      children={t("company_desc")}
                      sx={{ textIndent: 50 }}
                    />
                    <Typography
                      variant={"subtitle2"}
                      children={t("company_subdesc1")}
                    />
                    <Typography
                      variant={"subtitle2"}
                      children={t("company_subdesc2")}
                    />
                    <Typography
                      variant={"subtitle2"}
                      children={t("company_subdesc3")}
                    />
                  </Stack>
                </Grid>
                <Grid item xs={4}>
                  <Stack
                    direction={"column"}
                    justifyContent={"space-around"}
                    alignItems={"start"}
                    spacing={0.5}
                    sx={{
                      width: "100%",
                    }}
                  >
                    <Divider sx={{ width: "100%" }}>
                      <Typography
                        variant={"subtitle1"}
                        children={t("contact_us")}
                      />
                    </Divider>
                    {eList.fromArray(
                      [
                        {
                          i: <MapTwoTone />,
                          n: "149 ahmed lashin - taksem omar ebn el khatab - gesr el suez Cairo, Cairo Governorate, Egypt 11775",
                          l: "https://maps.app.goo.gl/eDqRuazBnXXV1Rch7",
                        },
                        {
                          i: <EmailTwoTone />,
                          n: "salesorder@originaltoolshome.com",
                          l: "mailto:salesorder@originaltoolshome.com",
                        },
                        {
                          i: <BsWhatsapp />,
                          n: "WhatsApp",
                          l: "https://api.whatsapp.com/send?phone=201023966756",
                        },
                        {
                          i: <PhoneTwoTone />,
                          n: "2 0102 396 6756",
                          l: "tel:201023966756",
                        },
                        {
                          i: <PhoneTwoTone />,
                          n: "2 0122 172 2221",
                          l: "tel:201221722221",
                        },
                      ],
                      (index, item) => (
                        <Button
                          key={`fcl-${index}`}
                          variant="text"
                          startIcon={item.i}
                          children={item.n}
                          href={item.l}
                          target="_blank"
                        />
                      )
                    )}
                  </Stack>
                </Grid>
              </Grid>
            </Toolbar>
          </Container>
        </AppBar>
        <AppBar position="static" variant="dense" color="white" sx={{}}>
          <Container maxWidth={"desktop"}>
            <Toolbar
              variant="dense"
              sx={{
                width: "100%",
                py: 0.5,
                px: 3,
                minHeight: "unset",
              }}
            >
              <Stack
                direction={"row"}
                justifyContent={"space-between"}
                alignItems={"start"}
                spacing={0.5}
                sx={{
                  width: "100%",
                }}
              >
                <Typography className="ltr enFonts" textAlign={"center"}>
                  {"Copyright Bayt Aleaded 2023"}
                </Typography>

                <Link
                  href="https://exabytellc.com"
                  target="_blank"
                  underline="hover"
                >
                  <Typography className="ltr enFonts" textAlign={"center"}>
                    {"Powered By Exabyte LLC"}
                  </Typography>
                </Link>
              </Stack>
            </Toolbar>
          </Container>
        </AppBar>
      </>
    )
  );
};
